# Initially generated by GitHub Copilot.
"""Compare vendored file copies to their MAM-basics sources.

Outputs a byte-comparison verdict + last-git-commit date for each copy.
Results written to out/vendoring_compare_out.txt.

WHY ``eol-only`` IS ITS OWN VERDICT

Until 2026-08-04 this hashed each file whole and reported two outcomes, so a copy
whose only difference was CRLF-on-disk was indistinguishable from one that had
genuinely drifted.  Ben's 2026-08-03 cross-repo review (minor 14, MAM-basics#219)
found the inventory saying a bare ``DIFFERS`` for all four of codex-index-aleppo's
``py/mb_cmn`` copies when three of them -- ``hebrew_points.py``, ``uni_denorm.py``,
``url_percent.py`` -- are blob-identical to the source and only ``str_defs.py``
carries real content drift.  Collapsing the CRLF case into ``identical`` would have
been the other available fix and is the wrong one: a working tree holding CRLF where
HEAD holds LF is the latent-CRLF condition that has inflated black diffs before
(hbofonts and codex-index-leningrad have it too), so it is a fact worth reporting --
just not the same fact as drift.  Hence three verdicts, and a token a ``DIFFERS``
grep does not catch.  The first three-verdict run, 2026-08-04, found 15 such copies
rather than the review's 3: book-of-job and diffable-pointed-hebrew hold the
condition as well, and had been reading as drift for the same reason.

WHAT THE NORMALIZATION DOES AND DOES NOT HIDE

``_normalize_newlines`` rewrites CRLF and lone CR to LF -- old-Mac CR endings
included, not CRLF alone.  It neither adds nor removes a terminator, so a copy that
merely lacks the source's final newline still reports ``DIFFERS``.  That is
deliberate: a trailing-newline difference is a difference in what lines the file
holds, not in how its lines end, and it is the kind of thing re-vendoring fixes.

``MISSING-DEST`` keeps its old meaning and its old precedence: an absent destination
is reported whether or not the source is there.  A present destination with an absent
source reports ``DIFFERS``, as it always did -- discovery derives every row from a
source file it has just listed, so that case does not arise in practice.
"""

import subprocess
import sys
from pathlib import Path

from mb_cmn import paths
from vendoring.discover import EOL_ONLY, iter_compare_copies, source_pkg_dirs

_MAM = paths.repo_root()
_REPOS = paths.repos_root()


def _normalize_newlines(data: bytes) -> bytes:
    """CRLF and lone CR -> LF.  Terminators only: none is added or removed."""
    return data.replace(b"\r\n", b"\n").replace(b"\r", b"\n")


def _identity(src_path: Path, dest_path: Path) -> str:
    """One of ``identical`` / ``eol-only`` / ``DIFFERS`` / ``MISSING-DEST``.

    Every value must be one whitespace-free token of at most 12 characters:
    ``gen_inventory._parse_compare_rows`` splits the fixed-width report on runs of
    two-or-more spaces, and the identity column is written ``<14`` plus one literal
    space, so a 13-character token would leave a single space and break the parse.
    """
    if not dest_path.exists():
        return "MISSING-DEST"
    if not src_path.exists():
        return "DIFFERS"
    src_bytes = src_path.read_bytes()
    dest_bytes = dest_path.read_bytes()
    if src_bytes == dest_bytes:
        return "identical"
    if _normalize_newlines(src_bytes) == _normalize_newlines(dest_bytes):
        return EOL_ONLY
    return "DIFFERS"


def _git_log_date(repo_path: Path, rel_file: str) -> str:
    """Return ISO date of last commit touching rel_file in repo_path, or '?'."""
    try:
        result = subprocess.run(
            ["git", "log", "-1", "--format=%ci", "--", rel_file],
            cwd=str(repo_path),
            capture_output=True,
            text=True,
            encoding="utf-8",
        )
        line = result.stdout.strip()
        if line:
            return line[:10]  # YYYY-MM-DD
        return "no-commits"
    except Exception as e:
        return f"err:{e}"


def main() -> None:
    sys.stdout.reconfigure(encoding="utf-8")
    source_pkg_dir_map = source_pkg_dirs()

    rows = []
    for filename, src_pkg, dest_repo, dest_rel, notes in iter_compare_copies():
        src_path = _MAM / source_pkg_dir_map[src_pkg] / filename
        dest_path = _REPOS / dest_repo / dest_rel

        identity_str = _identity(src_path, dest_path)
        last_synced = _git_log_date(_REPOS / dest_repo, dest_rel)

        rows.append(
            {
                "file": filename,
                "src_pkg": src_pkg,
                "dest_repo": dest_repo,
                "dest_path": dest_rel,
                "identity": identity_str,
                "last_synced": last_synced,
                "hint_notes": notes,
            }
        )

    out = _MAM / "out" / "vendoring_compare_out.txt"
    # newline="\n" because .gitattributes pins LF in this repo's WORKDIR too, and a
    # writer left on Windows text mode is the very latent-CRLF condition this program
    # now reports on elsewhere.
    with out.open("w", encoding="utf-8", newline="\n") as f:
        f.write(
            f"{'FILE':<42} {'DEST_REPO':<26} {'DEST_PATH':<55} {'IDENTITY':<14} {'LAST_SYNCED':<12} HINT_NOTES\n"
        )
        f.write("-" * 180 + "\n")
        for r in rows:
            f.write(
                f"{r['file']:<42} {r['dest_repo']:<26} {r['dest_path']:<55} {r['identity']:<14} {r['last_synced']:<12} {r['hint_notes']}\n"
            )

    print(f"Wrote {len(rows)} rows to {out}")
